    minute: { one: "%{count} minute ago", other: "%{count} minutes ago" }
  },
  today: "today",
  yesterday: "yesterday",
  tomorrow: "tomorrow",
  daysAgo: { one: "%{count} day ago", other: "%{count} days ago" },
  inDays: { one: "in %{count} day", other: "in %{count} days" }
}

export default class extends Controller {
  static targets = [ "time", "date", "datetime", "shortdate", "ago", "indays", "daysago", "agoorweekday", "timeordate" ]
  static values = { refreshInterval: Number, locale: String, translations: Object }
  static classes = [ "local-time-value"]

  #timer

  initialize() {
    const locale = this.#locale
    const translations = this.#translations

    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
    this.dateFormatter = new Intl.DateTimeFormat(locale, { dateStyle: "long" })
    this.shortdateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
    this.datetimeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short", dateStyle: "short" })
    this.agoFormatter = new AgoFormatter(translations)
    this.daysagoFormatter = new DaysAgoFormatter(translations)
    this.datewithweekdayFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
    this.indaysFormatter = new InDaysFormatter(translations)
    this.agoorweekdayFormatter = new DaysAgoOrWeekdayFormatter(locale, translations)
    this.timeordateFormatter = new TimeOrDateFormatter(locale)
  }

  connect() {
    this.#timer = setInterval(() => this.#refreshRelativeTimes(), 30_000)
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  refreshAll() {
    this.constructor.targets.forEach(targetName => {
      this.targets.findAll(targetName).forEach(target => {
        this.#formatTime(this[`${targetName}Formatter`], target)
      })
    })
  }

  refreshTarget(event) {
    const target = event.target;
    const targetName = target.dataset.localTimeTarget
    this.#formatTime(this[`${targetName}Formatter`], target)
  }

  timeTargetConnected(target) {
    this.#formatTime(this.timeFormatter, target)
  }

  dateTargetConnected(target) {
    this.#formatTime(this.dateFormatter, target)
  }

  datetimeTargetConnected(target) {
    this.#formatTime(this.datetimeFormatter, target)
  }

  shortdateTargetConnected(target) {
    this.#formatTime(this.shortdateFormatter, target)
  }

  agoTargetConnected(target) {
    this.#formatTime(this.agoFormatter, target)
  }

  indaysTargetConnected(target) {
    this.#formatTime(this.indaysFormatter, target)
  }

  daysagoTargetConnected(target) {
    this.#formatTime(this.daysagoFormatter, target)
  }

  agoorweekdayTargetConnected(target) {
    this.#formatTime(this.agoorweekdayFormatter, target)
  }

  timeordateTargetConnected(target) {
    this.#formatTime(this.timeordateFormatter, target)
  }

  get #locale() {
    const locale = this.hasLocaleValue && this.localeValue || document.documentElement.lang
    return (!locale || locale === "en") ? DEFAULT_LOCALE : locale
  }

  get #translations() {
    return this.hasTranslationsValue && Object.keys(this.translationsValue).length > 0 ? this.translationsValue : DEFAULT_TRANSLATIONS
  }

  #refreshRelativeTimes() {
    this.agoTargets.forEach(target => {
      this.#formatTime(this.agoFormatter, target)
    })
  }

  #formatTime(formatter, target) {
    const dt = secondsToDate(parseInt(target.getAttribute("datetime")))
    target.innerHTML = formatter.format(dt)
    target.title = this.datetimeFormatter.format(dt)
  }
}

class AgoFormatter {
  constructor(translations) {
    this.translations = translations
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#ago("year", years)
    if (months >= 1) return this.#ago("month", months)
    if (weeks >= 1) return this.#ago("week", weeks)
    if (days >= 1) return this.#ago("day", days)
    if (hours >= 1) return this.#ago("hour", hours)
    if (minutes >= 1) return this.#ago("minute", minutes)

    return this.translations.lessThanAMinuteAgo
  }

  #ago(unit, quantity) {
    return pluralize(this.translations.ago[unit], Math.floor(quantity))
  }
}

class DaysAgoFormatter {
  constructor(translations) {
    this.translations = translations
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(this.translations.today)
    if (days === 1) return styleableValue(this.translations.yesterday)
    return pluralize(this.translations.daysAgo, days, styleableValue(days))
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale, translations) {
    this.daysAgoFormatter = new DaysAgoFormatter(translations)
    this.weekdayFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return this.daysAgoFormatter.format(date)
    } else {
      return this.weekdayFormatter.format(date)
    }
  }
}

class InDaysFormatter {
  constructor(translations) {
    this.translations = translations
  }

  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(this.translations.today)
    if (days === 1) return styleableValue(this.translations.tomorrow)
    return pluralize(this.translations.inDays, days, styleableValue(days))
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.dateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
    this.timeFormatter = new Intl.DateTimeFormat(locale, { timeStyle: "short" })
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return this.dateFormatter.format(date)
    } else {
      return this.timeFormatter.format(date)
    }
  }
}

// Picks the "one" or "other" form and fills in the count. Languages without plural forms only provide "other".
function pluralize(forms, count, displayedCount = count) {
  const template = (count === 1 && forms.one) || forms.other
  return template.replace("%{count}", displayedCount)
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
