def leaves(h, prefix = [])
  h.flat_map { |k, v| v.is_a?(Hash) && !(v.keys.all? { PLURAL.include?(_1) } && v.key?("other")) ? leaves(v, prefix + [k]) : [(prefix + [k]).join(".")] }
end
