Dir["/app/app/**/*.{rb,erb,js}", "/app/lib/**/*.rb", "/app/config/**/*.rb"].each do |file|
  src = File.read(file)
  # explicit keys
  src.scan(/\bt\(\s*["']([a-z0-9_\.\/]+)["']/).flatten.each { |k| used[k] = true }
  src.scan(/I18n\.t\(\s*["']([a-z0-9_\.\/]+)["']/).flatten.each { |k| used[k] = true }
  src.scan(/default_i18n_subject/) { used[:subjects] = true }
  # lazy keys in views
  if file =~ %r{/app/views/(.*)\.[a-z_]+\.erb\z}
    scope = $1.split("/").map { |seg| seg.sub(/\A_/, "") }.join(".")
    src.scan(/\bt\(\s*["']\.([a-z0-9_]+)["']/).flatten.each { |k| used["#{scope}.#{k}"] = true }
  end
  # lazy keys in controllers: controller_path.action.key — collect the key suffix and mark any key ending with it
  if file =~ %r{/app/controllers/(.*)_controller\.rb\z}
    src.scan(/\bt\(\s*["']\.([a-z0-9_]+)["']/).flatten.each { |k| used["*#{$1}.*.#{k}"] = true }
  end
  # dynamic prefixes: t("some.prefix.#{...}")
  src.scan(/\bt\(\s*"([a-z0-9_\.]+)\.#\{/).flatten.each { |p| used["#{p}.*"] = true }
end
